"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[919],{51679:e=>{e.exports=JSON.parse('{"id":"2026-08-19-outboundcontent-timing-corrected","date":"2026-08-19","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Fixed","title":"outboundContent timing corrected on WhatsApp delivery receipts","excerpt":"The Delivery receipts for Outbound Messaging Apps(/connect/docs/delivery-receipts-for-outbound-chatapps) guide previously stated that the outboundContent object is attached to the receipt confirming delivery to the recipient (deliveredtorecipient). That was inaccurate.","hasArticle":true,"bodyHtml":"<p>The <a href=\\"/connect/docs/delivery-receipts-for-outbound-chatapps\\">Delivery receipts for Outbound Messaging Apps</a> guide previously stated that the <code>outboundContent</code> object is attached to the receipt confirming delivery to the recipient (<code>delivered_to_recipient</code>). That was inaccurate.</p>\\n<p><code>outboundContent</code> is <strong>WhatsApp only</strong>, and it is attached to the <strong>first receipt for the message</strong>, when <code>status.state</code> is <code>queued</code>. It is omitted from all subsequent receipts \u2014 <code>delivered_to_operator</code>, <code>delivered_to_recipient</code>, <code>read</code>, and so on. When the content cannot be reconstructed it is left out entirely.</p>\\n<p>No API behavior changed \u2014 this is a documentation accuracy fix. If you were previously looking for <code>outboundContent</code> on the delivered receipt, update your integration to read it from the <code>queued</code> receipt instead.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/delivery-receipts-for-outbound-chatapps\\">Delivery receipts for Outbound Messaging Apps</a></li>\\n</ul>\\n"}')}}]);